// Compile system snapshot for Gemini analysis
const containers = $('Get All Containers').item.json;
const dockerInfo = $('Get Docker Info').item.json;

const running = Array.isArray(containers) ? containers.filter(c => c.State === 'running') : [];
const stopped = Array.isArray(containers) ? containers.filter(c => c.State !== 'running') : [];
const unhealthy = running.filter(c => c.Status && c.Status.toLowerCase().includes('unhealthy'));

const containerLines = Array.isArray(containers)
  ? containers.map(c => `  ${c.Names?.[0]?.replace('/', '') || 'unknown'}: ${c.State} (${c.Status})`).join('\n')
  : 'Unable to retrieve container list';

const memTotal = dockerInfo.MemTotal ? Math.round(dockerInfo.MemTotal / 1024 / 1024 / 1024) + 'GB' : 'unknown';
const nContainers = dockerInfo.Containers || 'unknown';
const nRunning = dockerInfo.ContainersRunning || 'unknown';

const summary = `CRYPTEX Weekly System Snapshot
Date: ${new Date().toISOString()}
Host Memory: ${memTotal}
Total Containers: ${nContainers} (${nRunning} running)
Stopped: ${stopped.length}
Unhealthy: ${unhealthy.length}

Container Status:
${containerLines}`;

return { json: { summary, running: running.length, stopped: stopped.length, unhealthy: unhealthy.length } };

