parameters.jsCode:
const geminiResponse = $input.item.json;
const snapshot = $('Compile System Snapshot').item.json;

let aiInsight = 'AI analysis unavailable';
try {
  aiInsight = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || 'No response from Gemini';
} catch(e) { aiInsight = 'Gemini parse error: ' + e.message; }

const status = snapshot.stopped > 0 || snapshot.unhealthy > 0 ? '⚠️' : '✅';

const msg = `${status} CRYPTEX Weekly Digest — ${new Date().toLocaleDateString('en-US', {weekday:'long', year:'numeric', month:'long', day:'numeric'})}

📊 Containers: ${snapshot.running} running, ${snapshot.stopped} stopped, ${snapshot.unhealthy} unhealthy

🤖 Gemini Analysis:
${aiInsight}`;

return { json: { message: msg } };
